**Template Method for Sorting - Python**

```python
from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def __init__(self, data):
        self.data = list(data)

    # Template Method
    def sort(self):
        self._sort()
        return self.data

    @abstractmethod
    def _sort(self):
        pass

    # Helpers used by the algorithms
    def compare(self, a, b):
        return a < b

    def swap(self, i, j):
        self.data[i], self.data[j] = self.data[j], self.data[i]


class BubbleSort(SortAlgorithm):
    def _sort(self):
        n = len(self.data)
        for i in range(n):
            for j in range(0, n - i - 1):
                if not self.compare(self.data[j], self.data[j + 1]):
                    self.swap(j, j + 1)


class SelectionSort(SortAlgorithm):
    def _sort(self):
        n = len(self.data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(self.data[j], self.data[min_idx]):
                    min_idx = j
            if min_idx != i:
                self.swap(i, min_idx)


# Test
if __name__ == "__main__":
    nums = [64, 25, 12, 22, 11]
    strs = ["banana", "apple", "cherry"]

    print("BubbleSort nums:", BubbleSort(nums).sort())
    print("SelectionSort nums:", SelectionSort(nums).sort())

    print("BubbleSort strs:", BubbleSort(strs).sort())
    print("SelectionSort strs:", SelectionSort(strs).sort())
```

`SortAlgorithm.sort()` is the template method. Concrete algorithms `BubbleSort` and `SelectionSort` provide their own `_sort` implementation and reuse `compare()` / `swap()` from the base class.

